entries[86235] = { ["name"] = "Muster: Zornbalgbeinrüstung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer Zornbalgbeinrüstung.\nBenötigt Lederverarbeitung von Pandaria (50)\nBenötigt Goldener Lotus\n- Wohlwollend\n\nZornbalgbeinrüstung\nBenutzen: Bringt dauerhaft eine Rüstung an einer Hose an, die die Stärke um 8 und den kritischen Trefferwert um 4 erhöht.\n\nKann nur auf Beinrüstungen in Eurem Inventar angewandt werden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Prächtiger Balg , Geist der Harmonie" }
entries[86237] = { ["name"] = "Muster: Brustschutz der irdenen Harmonie", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Brustschutzes der irdenen Harmonie.\nBenötigt Lederverarbeitung von Pandaria (75)\nBenötigt Goldener Lotus\n- Wohlwollend\n\nBrustschutz der irdenen Harmonie\nWird beim Anlegen gebunden\nBrust Kette\n10 Rüstung\n+2 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 3.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Beweglichkeit\n\nHaltbarkeit 165 / 165\nVerkaufspreis:\nBenötigt Prächtiger Balg (3), Geist der Harmonie (8)" }
entries[86238] = { ["name"] = "Muster: Brustschutz der Nemesis", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Brustschutzes der Nemesis.\nBenötigt Lederverarbeitung von Pandaria (75)\nVerkaufspreis:\nBrustschutz der Nemesis\nWird beim Anlegen gebunden\nBrust Leder\n7 Rüstung\n+2 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 3.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Meisterschaft\n\nHaltbarkeit 165 / 165\nVerkaufspreis:\nBenötigt Prächtiger Balg (3), Geist der Harmonie (4), Blutgeist (8)" }
