entries[86478] = { ["name"] = "Qiangs \"Die Wissenschaft des Krieges\"", ["text"] = "Questgegenstand\nEinzigartig\n\"Qiang der Gnadenlose war ein Meister der Taktik und Strategie. Ein zufällig ausgewähltes Zitat dieser Abhandlung des Königs und Kriegsfürsten lautet 'Knochen mehren sich, wenn sie zermalmt werden.'\"" }
entries[86479] = { ["name"] = "Bogen von Subetai dem Schnellen", ["text"] = "Questgegenstand\nEinzigartig\n\"Niemand war so habgierig wie der Banditenkönig und niemandes Bogen war so schnell.\"" }
entries[86489] = { ["name"] = "Saftiges Schildkrötenfilet", ["text"] = "Questgegenstand\nBenutzen: Wirft Kovok das Filet zu. Schließlich ist er noch ein Insekt im Wachstum.\n\"Ein überraschend zartes Stück Fleisch von einem muskulösen Tier.\"" }
entries[86508] = { ["name"] = "Frisches Brot", ["text"] = "Herbeigezauberter Gegenstand\nBenutzen: Stellt im Verlauf von 10 Sek. 3526 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[86511] = { ["name"] = "Chos Feuerwerk", ["text"] = "Questgegenstand\n\"Auf alte Art gefertigt und vor Kurzem aus den Tiefen von Morgenblüte geborgen.\"" }
entries[86512] = { ["name"] = "Gesellenkochbuch", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Test\nVerkaufspreis:" }
entries[86513] = { ["name"] = "Roben der zerrissenen Alpträume", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n4 Rüstung\n+2 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Intelligenz\n\nHaltbarkeit 165 / 165\nVerkaufspreis:" }
entries[86514] = { ["name"] = "Fänge der sterbenden Hoffnung", ["text"] = "Wird beim Aufheben gebunden\nHände Leder\n4 Rüstung\n+2 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 1.\n\nPrismatischer Sockel\nSockelbonus: + 2 kritischer Trefferwert\n\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[86516] = { ["name"] = "Fragment des Schreckens", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[86517] = { ["name"] = "Erstarrtes Harz von Kri'vess", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[86518] = { ["name"] = "Feuerträger der Yaungol", ["text"] = "Wird an Kriegsmeute gebunden\nEinhändig Streitkolben\n5 - 7 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+3 Stärke\n+2 Ausdauer\nHaltbarkeit 90 / 90\nAnlegen: Eure Nahkampfangriffe verfügen über eine Chance, Eure Gegner in Brand zu setzen, was 10 Sek. lang alle 2 Sek. 0 Schaden verursacht. (Procchance: 10%)\nVerkaufspreis:" }
entries[86519] = { ["name"] = "Schnellstoßdolch des Windschnitters", ["text"] = "Wird an Kriegsmeute gebunden\nEinhändig Dolch\n3 - 5 Schaden Geschwindigkeit 1.80\n(2.2 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 65 / 65\nVerkaufspreis:" }
entries[86520] = { ["name"] = "Maliks tapferer Speer", ["text"] = "Wird an Kriegsmeute gebunden\nZweihändig Stangenwaffe\n7 - 15 Schaden Geschwindigkeit 3.60\n(3.1 Schaden pro Sekunde)\n+4 Beweglichkeit\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[86521] = { ["name"] = "Luzides Amulett des gewandten Geistes", ["text"] = "Wird an Kriegsmeute gebunden\nHals\n+2 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 3.\nVerkaufspreis:" }
entries[86522] = { ["name"] = "Klinge des Ersten", ["text"] = "Wird an Kriegsmeute gebunden\nEinhändig Schwert\n4 - 8 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 90 / 90\nVerkaufspreis:" }
entries[86523] = { ["name"] = "Schwärmendes Spaltbeil von Ka'roz", ["text"] = "Wird an Kriegsmeute gebunden\nZweihändig Schwert\n8 - 14 Schaden Geschwindigkeit 3.60\n(3.1 Schaden pro Sekunde)\n+4 Stärke\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[86524] = { ["name"] = "Mutationsstab des Sezierers", ["text"] = "Wird an Kriegsmeute gebunden\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+18 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[86525] = { ["name"] = "Blutgetränktes Chitinfragment", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure Meisterschaftswertung um + 6.\nAnlegen: Wenn Ihr ein Ziel tötet, das Erfahrung gewährt, erhaltet Ihr 'Wut des Blutsuchers', wodurch Ihr 2 Min. lang 0 Beweglichkeit erhaltet. Bis zu 10-mal stapelbar.\n\"Ein Panzerfragment von Skeer dem Blutsucher, das mit dem Blut seiner Feinde getränkt ist.\"\nVerkaufspreis:" }
entries[86526] = { ["name"] = "Medaillon des Schwarmwächters", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 6.\nAnlegen: Erhöht Eure Bewegungsgeschwindigkeit in der Schreckensöde um 10%.\nVerkaufspreis:" }
entries[86527] = { ["name"] = "Klinge des vergifteten Geistes", ["text"] = "Wird an Kriegsmeute gebunden\nEinhändig Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+12 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 90 / 90\nVerkaufspreis:" }
entries[86529] = { ["name"] = "Talisman des Manipulators", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Die Angriffe Eures Begleiters haben eine Chance, zusätzlich 50% Schaden als Naturschaden zu verursachen, jedoch nicht mehr als 26 . (Procchance: 10%)\nVerkaufspreis:" }
entries[86532] = { ["name"] = "Beutel mit Gasbomben der Shado-Pan", ["text"] = "Questgegenstand\nBenutzen: Platziert eine Shado-Pan-Gasbombe. Fügt Humanoiden, die keine Mantis sind, keinen Schaden zu. (20 Sek. Abklingzeit)\n\"Macht Schluss mit Mantis.\"" }
entries[86533] = { ["name"] = "Leuchtender Bern", ["text"] = "Questgegenstand\nEinzigartig\n\"Das sanfte Schimmern legt Euch nahe, dass es sich hierbei nicht um ein gewöhnliches Stück Bern handelt.\"" }
entries[86534] = { ["name"] = "Glänzende Münze der Shado-Pan", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nDauer: 18 std. (Realzeit)\nBenutzen: Wirft eine Shado-Pan-Münze, die die Aufmerksamkeit aller in der Nähe befindlichen Monster 10 Sek. lang auf sich zieht. Bricht Verstohlenheit nicht ab. Nur auf Sra'vess anwendbar. (3 Sek. Abklingzeit)\n\"Das Geräusch lenkt die Mantis ab, nicht der Wert.\"" }
entries[86536] = { ["name"] = "Wukaopfeil der Lethargie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (6)\nDauer: 18 std. (Realzeit)\nBenutzen: Macht ein Ziel bis zu 1 Min. lang handlungsunfähig. Muss im Verstohlenheitsmodus sein. Wirkt nur bei Sra'vess, die sich nicht im Kampf befinden. Jeglicher erlittene Schaden belebt das Ziel wieder. (3 Sek. Abklingzeit)\n\"Ein kunstvoll gearbeiteter Pfeil, der von den Wukao verwendet wird.\"" }
entries[86541] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Priester\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[86542] = { ["name"] = "Fliegender Tigergurami", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Angeln (1)\n\"Ein Fisch mit Flügeln? Wie ungewöhnlich.\"" }
entries[86544] = { ["name"] = "Stachelfischalpha", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Angeln (1)\n\"Nehmt Euch vor den Stacheln in Acht. Sie sehen aus, als könnten sie großen Schaden anrichten.\"" }
entries[86545] = { ["name"] = "Fintenfisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Angeln (1)\n\"Selbst nach ihrem Tod ändert diese seltsame Kreatur ihre Farben, um sich ihrer Umgebung anzupassen.\"" }
entries[86546] = { ["name"] = "Himmelskristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Entfernt den Wolkenschutz von Alani der Sturmgeborenen." }
entries[86547] = { ["name"] = "Himmelssplitter", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (10)\nBenutzen: Kombiniert 10 Himmelssplitter, um einen Himmelskristall herzustellen." }
entries[86550] = { ["name"] = "Lehrlingskochbuch", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Test\nVerkaufspreis:" }
entries[86551] = { ["name"] = "Expertenkochbuch", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Test\nVerkaufspreis:" }
entries[86552] = { ["name"] = "Fachmannskochbuch", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Test\nVerkaufspreis:" }
entries[86553] = { ["name"] = "Meisterkochbuch", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Test\nVerkaufspreis:" }
entries[86554] = { ["name"] = "Großmeisterkochbuch", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Test\nVerkaufspreis:" }
entries[86558] = { ["name"] = "Nudelholz", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nIn Schildhand geführt\nAnlegen: +10 Kochkunstfertigkeit von Pandaria.\n\nKochtradition (0/3)\nSchürze\nBratpfanne\nNudelholz\n(3) Set : +10 Kochkunstfertigkeit von Pandaria.\nVerkaufspreis:" }
entries[86559] = { ["name"] = "Bratpfanne", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nEinhändig\n1 Schaden Geschwindigkeit 2.00\n(0.5 Schaden pro Sekunde)\nAnlegen: +10 Kochkunstfertigkeit von Pandaria.\n\nKochtradition (0/3)\nSchürze\nBratpfanne\nNudelholz\n(3) Set : +10 Kochkunstfertigkeit von Pandaria.\nVerkaufspreis:" }
entries[86562] = { ["name"] = "Hopfling", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Hopfling beschwören oder wieder freigeben.\n80 ( 80)" }
entries[86563] = { ["name"] = "Hohles Schilfrohr", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Wasserschreiter beschwört.\nMit Rechtsklick Euren Wasserschreiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[86564] = { ["name"] = "Erfülltes Jadefragment", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Schleifer beschwört.\nMit Rechtsklick den Schleifer beschwören oder wieder freigeben.\n80 ( 80)" }
entries[86565] = { ["name"] = "Schlachthorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Schmettert in ein lautes Signalhorn, das Gegner innerhalb von 40 Metern anlockt. Funktioniert nicht bei Zielen, die nicht aus Pandaria stammen oder deren Stufe 49 überschreitet. (2 Min Abklingzeit)\n\"Wird von Yaungolspähern getragen, um im Falle eines Angriffs Verbündete zu alarmieren.\"" }
entries[86566] = { ["name"] = "Sammlerhandschuhe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHände Stoff\n1 Rüstung\nHaltbarkeit 20 / 20\nAnlegen: Ermöglicht schnelleres Sammeln von Ressourcen in Pandaria.\n\"Schützt gegen scharfkantige Steine und Dornen.\"" }
entries[86567] = { ["name"] = "Yaungolwindspiel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenutzen: Stürmt auf einen Gegner zu, fügt Gegnern in einem Umkreis von 8 Metern 32 körperlichen Schaden zu und stößt sie 2 Sek. lang zu Boden. (2 Min Abklingzeit)\n\"Wird von Yaungolmedizinmännern verwendet, um Wetteränderungen zu erahnen.\"\nVerkaufspreis:" }
entries[86568] = { ["name"] = "Handlanger Peins Messingkompass", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Setzt die Erinnerungen eines längst vergessenen Ersten Maats frei. (Procchance: 5%, 3Min. Abklingzeit) (2 Std. Abklingzeit)" }
entries[86569] = { ["name"] = "Kristall des Wahnsinns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erhöht 1 Stunde lang alle Werte um 9 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. (15 Min Abklingzeit)\n\"Es wirkt fast, als ob er Euch... anstarrt.\"" }
entries[86570] = { ["name"] = "Kiste mit entführten Welpen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenutzen: Befreit die entführten Welpen, die 10 Min. lang für Euch kämpfen. (1 Stunde Abklingzeit)\n\"...und sie essen Welpen!\"\nVerkaufspreis:" }
entries[86571] = { ["name"] = "Kangs Bindungsstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Erfüllt Euch mit Stein und gewährt eine Chance, nach dem Töten eines Gegners diesen in Stein zu hüllen. (Procchance: 33%, 1Min. Abklingzeit) (1 Stunde Abklingzeit)\n\"Die Steinbinder der Mogu nutzen diese runenverzierten Katalysatoren, um Fleisch in Stein zu verwandeln.\"" }
entries[86572] = { ["name"] = "Terrakottafragment", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenutzen: Beschwört einen Terrakottakrieger, der 10 Min. lang für Euch kämpft. (1 Stunde Abklingzeit)\n\"Mit mächtiger Mogumagie erfüllt.\"\nVerkaufspreis:" }
entries[86573] = { ["name"] = "Fragment des Abschlusssteins", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Verwandelt in eine Mogustatue und kann 5 Min. lang nicht als Ziel erfasst werden. (30 Min Abklingzeit)\n\"Ein Fragment unbekannter Herkunft, das von uralter Magie erfüllt ist.\"" }
entries[86574] = { ["name"] = "Elixier des uralten Wissens", ["text"] = "\"Ein leises Flüstern ist aus dem Fläschchen zu vernehmen.\"\nVerkaufspreis:" }
entries[86575] = { ["name"] = "Kelch der Geheimnisse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Gebt Euch Eurem Zorn 10 Sek. lang hin. Während der Wirkungsdauer verwandelt Euch der nächste Todesstoß, den Ihr gegen einen Spielercharakter erzielt, 6.3 Sek. lang in einen Mogu. Als Mogu könnt Ihr keine anderen Aktionen ausführen, während Ihr den Gegner verhöhnt. (10 Min Abklingzeit)\n\"Rituale, um die Leichen gefallener Feinde zu entweihen, waren in der Mogukultur weit verbreitet.\"" }
entries[86576] = { ["name"] = "Dynastie des Stahls", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenutzen: Beschwört einen Klingentornado, der 10 Min. lang für Euch kämpft. (1 Stunde Abklingzeit)\n\"Die Schwertkunst der Mantis ist ein sorgsam gehütetes Geheimnis.\"\nVerkaufspreis:" }
entries[86577] = { ["name"] = "Rute des Bernformens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Hüllt das Ziel in Bern und verhindert bis zu 1 Min. lang jegliche Handlung. Jeglicher Schaden zerbricht den Bern. Kann nicht gegen Spielercharaktere oder Ziele über Stufe 49 eingesetzt werden. (5 Min Abklingzeit)\n\"Wird von den Bernwebern der Mantis verwendet, um Konstruktionen oder gehärteten Bern herzustellen.\"" }
entries[86578] = { ["name"] = "Siegel des ewigen Kriegers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Regeneriert 6 Sek. lang alle 1 Sek. 15% Gesundheit und Mana. Jeglicher erlittene Schaden beendet die Raserei. Kann nur in Pandaria genutzt werden. (5 Min Abklingzeit)\n\"An Shek'zeers Elitewächter für treue Dienste verliehen.\"" }
entries[86580] = { ["name"] = "Verwelktes Seerosenblatt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Paladin , Jäger , Schurke , Priester , Todesritter , Schamane , Magier , Hexenmeister , Mönch\n\"Dieses Exemplar ist dem Klimawandel erlegen.\"\nVerkaufspreis:" }
entries[86581] = { ["name"] = "Weitwassermuschelhorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Lässt Euch weit in die Ferne blicken und gewährt die Fähigkeit, kleine Wassertropfen zu erzeugen. (10 Min Abklingzeit)\n\"Das Muschelhorn ist mit Jinyurunen beschrieben, die es dem Benutzer ermöglichen, die Sprache der Wellen zu verstehen.\"" }
entries[86582] = { ["name"] = "Wasserjuwel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Erhöht die Schwimmgeschwindigkeit um 50% und gestattet Unterwasseratmung. Hält 10 Min. lang an. Kann nur in Pandaria genutzt werden. (1 Stunde Abklingzeit)\n\"Aus dem Schlund von Gokk'lok erbeutet.\"" }
entries[86583] = { ["name"] = "Schlachtbanner von Salyis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Versteckt Euch 1 Sek. lang in den Schatten und beschwört einen Kriegsspäher von Salyis. Der Kriegsspäher zieht die Aufmerksamkeit von Monstern in der Nähe auf sich und rennt davon. Nur wirksam in Pandaria. (10 Min Abklingzeit)\n\"Mit dem Blut vieler glückloser Abenteurer getränkt.\"" }
entries[86584] = { ["name"] = "Gehärteter Panzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Wirft einen harten Panzer, der das Ziel aus dem Sattel stößt. Funktioniert nicht bei Zielen über Stufe 49.. (15 Min Abklingzeit)\n\"Unfair!\"" }
entries[86585] = { ["name"] = "Goldenes Vlies", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nAnlegen: Getötete Gegner, die Erfahrung oder Ehre gewähren, können zusätzliche Goldbeute gewähren. (Procchance: 10%, 10Min. Abklingzeit)\n\"Wird unter den Saurok als Zeichen von Reichtum und Status betrachtet.\"\nVerkaufspreis:" }
entries[86586] = { ["name"] = "Pandarische Panflöte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Spielt auf der Panflöte, woraufhin Euch Kleintiere in der Nähe 15 Min. lang folgen. (1 Min Abklingzeit)" }
entries[86587] = { ["name"] = "Samen des ruhigen Wachstums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenutzen: Beschwört einen ruhigen Sprössling, der Euch 10 Min. lang heilt. (1 Stunde Abklingzeit)\n\"Pulsierende Lebensenergie entspringt diesem Samen.\"\nVerkaufspreis:" }
entries[86588] = { ["name"] = "Pandarischer Raketenzünder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bereitet ein beeindruckendes Feuerwerk vor. (30 Min Abklingzeit)\n\"Hier geht's ab!\"" }
entries[86589] = { ["name"] = "Ai-Lis Himmelsspiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Nehmt das etwas verzerrte Aussehen des Ziels an. Hält 10 Min. lang an. (1 Stunde Abklingzeit)\n\"Von einem sich stetig bewegenden Wolkenring umgeben.\"" }
entries[86590] = { ["name"] = "Essenz der Brise", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Löst eine leichte Brise aus, die Eure Schritte leichter macht. Dieser Effekt zeigt nur in Pandaria Wirkung. (1 Stunde Abklingzeit)" }
entries[86591] = { ["name"] = "Magische Banane", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wirft eine magische Banane auf den Boden, die die nächste Person zu Fall bringen wird, die über sie läuft. (2 Std. Abklingzeit)" }
entries[86592] = { ["name"] = "Ho-zen-Friedenspfeife", ["text"] = "Benutzen: Erhöht den Ruf bei den Einwohnern Pandarias um 1000. (7 Tagen Abklingzeit)" }
entries[86593] = { ["name"] = "Ho-zen-Wasserball", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Macht Euch auf Sommerspaß gefasst! (1 Stunde Abklingzeit)" }
entries[86594] = { ["name"] = "Pfeife des hilfreichen Nupsi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Ruft das hilfreiche Nupsi, das für Euch nach Futter sucht und Geschenke zurückbringt. Kann nur in Pandaria genutzt werden. (2 Std. Abklingzeit)\n\"Darauf wurde wohl heftig herumgekaut.\"" }
entries[86595] = { ["name"] = "Beutel mit hilfreichen Sachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>" }
entries[86596] = { ["name"] = "Nats Angelstuhl", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Einen bequemen Angelstuhl aufstellen. (5 Min Abklingzeit)\n\"Hat sogar einen Getränkehalter!\"" }
entries[86597] = { ["name"] = "Waffenkette aus lebendigem Stahl", ["text"] = "Wird beim Anlegen gebunden\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert und Euren kritischen Trefferwert um 13 erhöht. Ist nicht mit ähnlichen Effekten stapelbar. Durch das Anbringen der Waffenkette wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden." }
entries[86598] = { ["name"] = "Vor'thik-Eier", ["text"] = "Questgegenstand" }
entries[86599] = { ["name"] = "Geistereisenschildstachel", ["text"] = "Wird beim Anlegen gebunden\nBenutzen: Bringt einen Geistereisenstachel an Eurem Schild an, der beim Blocken manchmal 42 Schaden verursacht.\n\nDurch das Anbringen des Geistereisenstachels wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[86607] = { ["name"] = "Goblindrachengewehr - Nr. II", ["text"] = "Benutzen: Entfesselt eine Blitzentladung, die Zielen in einem 10 Meter großen kegelförmigen Bereich vor dem Wirkenden 4 Sek. lang alle 0.5 Sek. 48 Naturschaden zufügt.\n\nKann während der Bewegung gewirkt werden. (30 Sek. Abklingzeit)\n50 Aufladungen\nVerkaufspreis:" }
entries[86616] = { ["name"] = "Schreckensbernfokus", ["text"] = "Questgegenstand\n\"Konzentrierte Angst, die in kristallisiertem Kyparitharz gebunden wurde.\"" }
